1	//! inkseal 的库接口：对任意实现 [`std::io::Read`] 的输入计算 SHA-256 摘要，
2	//! 以及导入 DER 编码（SubjectPublicKeyInfo）的 Ed25519 公钥。
3	//!
4	//! 摘要只取决于输入的原始字节，与命令行 `inkseal digest <文件>` 遵循同一内容规则。
5	//! 公钥导入只确认编码被接受，不表示已验证任何签名或确认公钥持有者的身份。
6	
7	use sha2::{Digest, Sha256};
8	use std::error::Error;
9	use std::fmt;
10	use std::io::{self, Read};
11	
12	/// SHA-256 摘要结果，可表示为 64 个小写十六进制字符。
13	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
14	pub struct Sha256Digest([u8; 32]);
15	
16	impl Sha256Digest {
17	    /// 返回摘要的原始 32 字节。
18	    pub fn as_bytes(&self) -> &[u8; 32] {
19	        &self.0
20	    }
21	
22	    /// 返回 64 个小写十六进制字符，与命令行输出一致（不含换行）。
23	    pub fn to_hex(&self) -> String {
24	        let mut hex = String::with_capacity(64);
25	        for byte in self.0 {
26	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
27	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
28	        }
29	        hex
30	    }
31	
32	    /// 从十六进制文本的原始字节解析摘要。
33	    ///
34	    /// 这是摘要文字还原的唯一规则：[`FromStr`] 只是在 `&str` 上委托给本
35	    /// 方法，命令行核对摘要时也直接使用它，因此从文本解析、按值比较与再次
36	    /// 显示永远遵循同一套规则。接受 `0-9`、`a-f` 和 `A-F`，大小写混用表示
37	    /// 同一个 32 字节值；解析结果可与 [`digest_reader`] 的结果直接比较，
38	    /// 再经 [`to_hex`](Self::to_hex) 显示时始终是完整的 64 个小写十六进制
39	    /// 字符，前导零不会丢失。
40	    ///
41	    /// 入参按原始字节处理，不要求是合法 UTF-8（例如操作系统给出的命令行
42	    /// 参数可能无法解码）：长度先按字节数判断，必须恰好为 64；长度正确时
43	    /// 报告首个非法字节从零开始的字节偏移。不做任何裁剪或修正，空白、末尾
44	    /// 换行、`0x` 前缀以及非 ASCII 字节都属于格式错误。
45	    pub fn from_hex_bytes(bytes: &[u8]) -> Result<Sha256Digest, ParseDigestError> {
46	        if bytes.len() != 64 {
47	            return Err(ParseDigestError::InvalidLength(bytes.len()));
48	        }
49	        let mut out = [0u8; 32];
50	        for (i, pair) in bytes.chunks_exact(2).enumerate() {
51	            let hi = hex_nibble(pair[0])
52	                .ok_or(ParseDigestError::InvalidHexChar(2 * i))?;
53	            let lo = hex_nibble(pair[1])
54	                .ok_or(ParseDigestError::InvalidHexChar(2 * i + 1))?;
55	            out[i] = (hi << 4) | lo;
56	        }
57	        Ok(Sha256Digest(out))
58	    }
59	}
60	
61	impl fmt::Display for Sha256Digest {
62	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
63	        f.write_str(&self.to_hex())
64	    }
65	}
66	
67	impl fmt::Debug for Sha256Digest {
68	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
69	        write!(f, "Sha256Digest({self})")
70	    }
71	}
72	
73	/// 从十六进制文本解析 [`Sha256Digest`] 失败时返回的类型化错误。
74	///
75	/// 两类失败可以按变体区分：长度不符时携带输入的实际 UTF-8 字节长度；
76	/// 长度正确但含非法字符时携带首个非法字节从零开始的字节偏移。
77	#[derive(Debug, Clone, Copy, PartialEq, Eq)]
78	pub enum ParseDigestError {
79	    /// 输入的 UTF-8 字节长度不是 64；携带实际字节长度。
80	    InvalidLength(usize),
81	    /// 长度为 64 但含有非十六进制字符；携带首个非法字节的字节偏移
82	    /// （按原始文本的字节计算，不按字符个数）。
83	    InvalidHexChar(usize),
84	}
85	
86	impl ParseDigestError {
87	    /// 长度不符时返回输入的实际字节长度，否则返回 `None`。
88	    pub fn actual_length(&self) -> Option<usize> {
89	        match self {
90	            ParseDigestError::InvalidLength(len) => Some(*len),
91	            ParseDigestError::InvalidHexChar(_) => None,
92	        }
93	    }
94	
95	    /// 含非法字符时返回首个非法字节的字节偏移，否则返回 `None`。
96	    pub fn invalid_position(&self) -> Option<usize> {
97	        match self {
98	            ParseDigestError::InvalidLength(_) => None,
99	            ParseDigestError::InvalidHexChar(pos) => Some(*pos),
100	        }
101	    }
102	}
103	
104	impl fmt::Display for ParseDigestError {
105	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
106	        match self {
107	            ParseDigestError::InvalidLength(len) => write!(
108	                f,
109	                "digest must be exactly 64 ASCII hexadecimal characters, got {len} bytes"
110	            ),
111	            ParseDigestError::InvalidHexChar(pos) => {
112	                write!(f, "digest contains a non-hexadecimal byte at offset {pos}")
113	            }
114	        }
115	    }
116	}
117	
118	impl Error for ParseDigestError {}
119	
120	fn hex_nibble(b: u8) -> Option<u8> {
121	    match b {
122	        b'0'..=b'9' => Some(b - b'0'),
123	        b'a'..=b'f' => Some(b - b'a' + 10),
124	        b'A'..=b'F' => Some(b - b'A' + 10),
125	        _ => None,
126	    }
127	}
128	
129	impl std::str::FromStr for Sha256Digest {
130	    type Err = ParseDigestError;
131	
132	    /// 从 64 个 ASCII 十六进制字符解析摘要。
133	    ///
134	    /// 接受 `0-9`、`a-f` 和 `A-F`，大小写混用表示同一个摘要。输入必须
135	    /// 恰好是 64 个字符：不做任何裁剪或修正，空白、末尾换行、`0x` 前缀、
136	    /// 分隔符以及全角数字等非 ASCII 内容都属于格式错误。长度按输入的
137	    /// UTF-8 字节数判断，非法字符的位置也按字节偏移报告。
138	    fn from_str(s: &str) -> Result<Self, Self::Err> {
139	        Sha256Digest::from_hex_bytes(s.as_bytes())
140	    }
141	}
142	
143	/// 计算摘要过程中读取输入失败时返回的类型化错误。
144	#[derive(Debug)]
145	pub struct DigestError(io::Error);
146	
147	impl DigestError {
148	    /// 取出底层的 I/O 错误。
149	    pub fn into_inner(self) -> io::Error {
150	        self.0
151	    }
152	}
153	
154	impl fmt::Display for DigestError {
155	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
156	        write!(f, "failed to read input: {}", self.0)
157	    }
158	}
159	
160	impl Error for DigestError {
161	    fn source(&self) -> Option<&(dyn Error + 'static)> {
162	        Some(&self.0)
163	    }
164	}
165	
166	impl From<io::Error> for DigestError {
167	    fn from(err: io::Error) -> Self {
168	        DigestError(err)
169	    }
170	}
171	
172	/// 以流式方式读取 `reader` 的全部字节并计算 SHA-256 摘要。
173	///
174	/// 内存占用与输入大小无关。读取失败时返回 [`DigestError`]，绝不返回部分内容的摘要。
175	///
176	/// [`io::ErrorKind::Interrupted`] 是临时中断而非输入结束：本次读取没有
177	/// 消费任何字节，直接重试同一位置，摘要与未发生中断时完全一致。其他
178	/// 错误（权限不足、数据损坏等）仍然立即失败。
179	pub fn digest_reader<R: Read>(mut reader: R) -> Result<Sha256Digest, DigestError> {
180	    let mut hasher = Sha256::new();
181	    let mut buf = [0u8; 64 * 1024];
182	    loop {
183	        match reader.read(&mut buf) {
184	            Ok(0) => break,
185	            Ok(n) => hasher.update(&buf[..n]),
186	            Err(ref err) if err.kind() == io::ErrorKind::Interrupted => continue,
187	            Err(err) => return Err(DigestError(err)),
188	        }
189	    }
190	    Ok(Sha256Digest(hasher.finalize().into()))
191	}
192	
193	/// Ed25519 公钥，由 DER 编码的 SubjectPublicKeyInfo 导入。
194	///
195	/// 与 [`Sha256Digest`] 是两个明确区分的类型：公钥不是摘要，不能把公钥
196	/// 当作摘要解析，也不能用摘要的十六进制解析入口还原公钥。文本表示固定
197	/// 为 64 个小写十六进制字符（保留前导零，不含标签或换行），表示公钥
198	/// 本身的 32 字节，**不是**公钥的 SHA-256 摘要。
199	#[derive(Clone, Copy, PartialEq, Eq, Hash)]
200	pub struct Ed25519PublicKey([u8; 32]);
201	
202	impl Ed25519PublicKey {
203	    /// 从 DER 编码的 SubjectPublicKeyInfo（RFC 8410）原始字节导入公钥。
204	    ///
205	    /// 入参是**二进制**的公钥容器：恰好一份完整、规范的 DER 对象。
206	    /// 裸公钥、十六进制文本和 PEM 文本都不属于本入口接受的格式，不做
207	    /// 任何格式猜测或文本转换。
208	    ///
209	    /// 接受范围遵循 RFC 8410 对 Ed25519 公钥的规定：算法标识为
210	    /// `1.3.101.112`，算法参数必须缺省（即使写成 NULL 也拒绝），公钥
211	    /// 所在位串的未使用位数为零，公钥内容恰好 32 字节。截断数据、声明
212	    /// 长度与实际内容不符、非规范长度编码、容器中出现多余字段或对象
213	    /// 之后还有字节都返回 [`ImportPublicKeyError::Malformed`]，不忽略
214	    /// 剩余内容，也不自动补齐。
215	    ///
216	    /// 公钥长度是 Ed25519 专属的算法约束，只在算法已确认为 Ed25519
217	    /// 之后检查。因此一份完整、规范但属于其他算法的容器——例如 RFC 8410
218	    /// 的 Ed448 公钥（算法标识 `1.3.101.113`，公钥内容 57 字节）——
219	    /// 不会因为长度不是 32 而被当成格式损坏，而是返回
220	    /// [`ImportPublicKeyError::UnsupportedAlgorithm`]，携带实际标识
221	    /// `1.3.101.113` 供调用方展示；调用方需要的是 Ed25519 公钥，应当
222	    /// 更换公钥，而不是去“修复”这份本来就完整的编码。整体编码已损坏
223	    /// （截断、长度不符、参数写成 NULL、未使用位数非零、对象之后还有
224	    /// 字节等）时一律返回 [`ImportPublicKeyError::Malformed`]，即使局部
225	    /// 能看到 Ed448 等其他算法标识，也不会改报算法不支持。
226	    ///
227	    /// 导入成功只表示编码被接受：不表示已验证任何文件签名，也不表示
228	    /// 确认了公钥持有者的身份。
229	    pub fn from_spki_der(der: &[u8]) -> Result<Ed25519PublicKey, ImportPublicKeyError> {
230	        const MALFORMED: ImportPublicKeyError = ImportPublicKeyError::Malformed;
231	
232	        // 外层：恰好一个 SEQUENCE，对象之后不允许有任何字节。
233	        let (tag, spki, rest) = read_der_tlv(der).ok_or(MALFORMED)?;
234	        if tag != TAG_SEQUENCE || !rest.is_empty() {
235	            return Err(MALFORMED);
236	        }
237	        // SubjectPublicKeyInfo 内部：恰好 algorithm 与 subjectPublicKey 两项。
238	        let (tag, algorithm, rest) = read_der_tlv(spki).ok_or(MALFORMED)?;
239	        if tag != TAG_SEQUENCE {
240	            return Err(MALFORMED);
241	        }
242	        let (tag, bit_string, rest) = read_der_tlv(rest).ok_or(MALFORMED)?;
243	        if tag != TAG_BIT_STRING || !rest.is_empty() {
244	            return Err(MALFORMED);
245	        }
246	        // AlgorithmIdentifier 内部：恰好一个 OID，没有任何参数——
247	        // RFC 8410 要求参数缺省，写成 NULL 同样拒绝。
248	        let (tag, oid_content, rest) = read_der_tlv(algorithm).ok_or(MALFORMED)?;
249	        if tag != TAG_OID || !rest.is_empty() {
250	            return Err(MALFORMED);
251	        }
252	        let algorithm_oid = decode_oid(oid_content).ok_or(MALFORMED)?;
253	        // 位串的未使用位数为零是与算法无关的结构约束：非零就是编码损坏。
254	        // 公钥长度则是 Ed25519 专属的算法约束，必须在确认算法之后再判断——
255	        // 否则一份完整的 Ed448（公钥 57 字节）容器会被误报成格式损坏，
256	        // 调用方无法区分“选错了算法”和“公钥文件真的坏了”。
257	        let (&unused_bits, key) = bit_string.split_first().ok_or(MALFORMED)?;
258	        if unused_bits != 0 {
259	            return Err(MALFORMED);
260	        }
261	
262	        // 只有整体结构完整、DER 合法时才判断算法：编码已损坏的输入
263	        // 一律报格式错误，不因局部看到其他算法标识而改报算法不支持。
264	        if algorithm_oid.arcs() != [1, 3, 101, 112] {
265	            return Err(ImportPublicKeyError::UnsupportedAlgorithm(algorithm_oid));
266	        }
267	
268	        // 算法确为 Ed25519：公钥内容必须恰好 32 字节，多一个少一个都是
269	        // 格式错误，绝不截短或补齐后接受。
270	        let Ok(key32) = <&[u8; 32]>::try_from(key) else {
271	            return Err(MALFORMED);
272	        };
273	        Ok(Ed25519PublicKey(*key32))
274	    }
275	
276	    /// 返回公钥的原始 32 字节。
277	    pub fn as_bytes(&self) -> &[u8; 32] {
278	        &self.0
279	    }
280	
281	    /// 返回 64 个小写十六进制字符（保留前导零，不含标签或换行）。
282	    ///
283	    /// 这是公钥本身的文本表示，不是公钥的 SHA-256 摘要。
284	    pub fn to_hex(&self) -> String {
285	        let mut hex = String::with_capacity(64);
286	        for byte in self.0 {
287	            hex.push(char::from_digit((byte >> 4) as u32, 16).unwrap());
288	            hex.push(char::from_digit((byte & 0x0f) as u32, 16).unwrap());
289	        }
290	        hex
291	    }
292	}
293	
294	impl fmt::Display for Ed25519PublicKey {
295	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
296	        f.write_str(&self.to_hex())
297	    }
298	}
299	
300	impl fmt::Debug for Ed25519PublicKey {
301	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
302	        write!(f, "Ed25519PublicKey({self})")
303	    }
304	}
