    fn base128_encode(mut value: u128) -> Vec<u8> {
        let mut bytes = vec![(value as u8) & 0x7f];
        value >>= 7;
        while value > 0 {
            bytes.push(0x80 | ((value as u8) & 0x7f));
            value >>= 7;
        }
        bytes.reverse();
        bytes
    }

