    fn oid_content(arcs: &[u128]) -> Vec<u8> {
        assert!(!arcs.is_empty());
        let first = 40 * arcs[0] + arcs[1];
        let mut content = base128_encode(first);
        for &arc in &arcs[2..] {
            content.extend_from_slice(&base128_encode(arc));
        }
        content
